<?php
namespace App\Livewire\Admin\Leave;use App\Enums\LeaveStatus;use App\Models\Leave;use Livewire\Attributes\Url;use Livewire\Component;use Livewire\WithPagination;
class Index extends Component{use WithPagination;#[Url]public string $status='';public function cancel(int $id):void{$leave=Leave::where('user_id',auth()->id())->findOrFail($id);abort_unless($leave->isPending(),422);$leave->update(['status'=>LeaveStatus::CANCELLED]);}public function render(){$q=Leave::with(['user','approver'])->when(!(auth()->user()->isHR()||auth()->user()->isAdmin()),fn($q)=>$q->where('user_id',auth()->id()))->when($this->status,fn($q)=>$q->where('status',$this->status));return view('livewire.admin.leave.index',['leaves'=>$q->latest()->paginate(25),'statuses'=>LeaveStatus::getOptions(),'canReview'=>auth()->user()->isHR()||auth()->user()->isAdmin()])->layout('components.layouts.admin',['title'=>'Leave requests']);}}
